//! Criterion benchmarks for filling `Histogram1D`.
//!
//! Run with `cargo bench -p tpt-dynamics-data --bench histogram`. The inputs are
//! generated from a fixed seed, so runs are comparable. Only the fill loop is timed.
//! The inputs are built once, outside the timed closure.

// The entry point generated by criterion_main! has no docs and cannot carry them.
#![allow(missing_docs)]

use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};
use tpt_dynamics_data::hist1d::Histogram1D;
use tpt_dynamics_data::rng::SplitMix64;

const SEED: u64 = 0x5eed_0001;
const NBINS: usize = 100;
const LO: f64 = 0.0;
const HI: f64 = 100.0;

/// Uniform values over the histogram range plus a few percent of out-of-range values,
/// so the under- and overflow branches are part of the measurement.
fn uniform_values(n: usize) -> Vec<f64> {
    let mut rng = SplitMix64::new(SEED);
    (0..n).map(|_| rng.uniform(LO - 5.0, HI + 5.0)).collect()
}

/// Exponentially distributed values, the shape of a falling transverse-momentum spectrum.
fn exponential_values(n: usize) -> Vec<f64> {
    let mut rng = SplitMix64::new(SEED ^ 0xa5a5);
    (0..n).map(|_| rng.exponential(15.0)).collect()
}

fn fill_unweighted(c: &mut Criterion) {
    let mut group = c.benchmark_group("hist1d/fill");
    for &n in &[10_000_usize, 1_000_000] {
        let values = uniform_values(n);
        group.throughput(Throughput::Elements(n as u64));
        group.bench_with_input(BenchmarkId::new("uniform", n), &values, |b, values| {
            b.iter(|| {
                let mut h = Histogram1D::uniform(NBINS, LO, HI).expect("valid binning");
                for &x in values {
                    h.fill(black_box(x));
                }
                black_box(h.integral())
            });
        });
    }
    group.finish();
}

fn fill_weighted(c: &mut Criterion) {
    let n = 1_000_000_usize;
    let values = exponential_values(n);
    let mut rng = SplitMix64::new(SEED ^ 0x0f0f);
    let weights: Vec<f64> = (0..n).map(|_| 0.5 + rng.next_f64()).collect();

    let mut group = c.benchmark_group("hist1d/fill_weighted");
    group.throughput(Throughput::Elements(n as u64));
    group.bench_function(BenchmarkId::new("exponential", n), |b| {
        b.iter(|| {
            let mut h = Histogram1D::uniform(NBINS, LO, HI).expect("valid binning");
            for (&x, &w) in values.iter().zip(&weights) {
                h.fill_weighted(black_box(x), w);
            }
            black_box(h.integral())
        });
    });
    group.finish();
}

fn fill_variable_binning(c: &mut Criterion) {
    let n = 1_000_000_usize;
    let values = exponential_values(n);
    // Quadratically spaced edges: finer bins at low pt, the usual HEP choice.
    let edges: Vec<f64> = (0..=NBINS).map(|i| HI * (i as f64 / NBINS as f64).powi(2)).collect();

    let mut group = c.benchmark_group("hist1d/fill_variable");
    group.throughput(Throughput::Elements(n as u64));
    group.bench_function(BenchmarkId::new("quadratic_edges", n), |b| {
        b.iter(|| {
            let mut h = Histogram1D::variable(&edges).expect("valid edges");
            for &x in &values {
                h.fill(black_box(x));
            }
            black_box(h.integral())
        });
    });
    group.finish();
}

criterion_group!(benches, fill_unweighted, fill_weighted, fill_variable_binning);
criterion_main!(benches);
